const navDocs = document.getElementById('nav-docs');
const tip = document.getElementById('ai4a11y-hover-tip');
const isEnabled = !!document.getElementById('ai4a11y-persistent-hover-styles');
if (!navDocs) return false;
if (!isEnabled) return tip === null;

navDocs.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
if (tip.hidden) return false;

const rect = tip.getBoundingClientRect();
const fitsHorizontally = rect.left >= 0 && rect.right <= window.innerWidth;
const fitsVertically = rect.top >= 0 && rect.bottom <= window.innerHeight;

document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
return fitsHorizontally && fitsVertically;

